import json


def parse_pesan(teks):
    try:
        data = json.loads(teks)
    except json.JSONDecodeError:
        raise ValueError("bukan JSON")
    if not isinstance(data, dict):
        raise ValueError("bukan objek")
    id_ = data.get("id")
    if not isinstance(id_, str) or not id_.strip():
        raise ValueError("id tidak sah")
    nilai = {}
    for kunci, bawah, atas in (("t", -40, 125), ("rh", 0, 100)):
        v = data.get(kunci)
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError(kunci + " bukan angka")
        if not (bawah <= v <= atas):
            raise ValueError(kunci + " di luar rentang")
        nilai[kunci] = v
    return {"id": id_, "t": nilai["t"], "rh": nilai["rh"]}


def cocok(filter_, topik):
    f = filter_.split("/")
    t = topik.split("/")
    for i, bagian in enumerate(f):
        if bagian == "#":
            return True
        if i >= len(t):
            return False
        if bagian != "+" and bagian != t[i]:
            return False
    return len(f) == len(t)


class Pengendali:
    def __init__(self, atas=30.0, bawah=27.0):
        self.atas = atas
        self.bawah = bawah
        self.kipas = False
        self.otomatis = True
        self.ditolak = 0
        self.suhu = []

    def proses(self, topik, teks):
        if not cocok("gh/+/sensor/#", topik):
            return None
        try:
            data = parse_pesan(teks)
        except ValueError:
            self.ditolak += 1
            return None
        self.suhu.append(data["t"])
        if self.otomatis:
            if data["t"] > self.atas:
                self.kipas = True
            elif data["t"] < self.bawah:
                self.kipas = False
        return self.kipas

    def rata_suhu(self):
        if not self.suhu:
            return 0.0
        return round(sum(self.suhu) / len(self.suhu), 1)

