def termasuk_rollout(id_perangkat, persen):
    bucket = sum(ord(c) for c in id_perangkat) % 100
    return bucket < persen


def daftar_rollout(daftar_id, persen):
    return [i for i in daftar_id if termasuk_rollout(i, persen)]
